-- ── (a1) Iqbal: corrected achievements / quotes / legacy section ──
UPDATE personalities SET
  image_url = 'https://upload.wikimedia.org/wikipedia/commons/a/ac/Allama_Iqbal.jpg',
  image_credit = 'Iqbal Academy Pakistan',
  image_licence = 'Public domain',
  achievements = $wch$[{"icon": "🖊️", "title": "National Poet of Pakistan", "description": "Declared Shair-e-Mashriq (Poet of the East) and national poet of Pakistan."}, {"icon": "🎓", "title": "PhD from Munich (1908)", "description": "Earned his doctorate in philosophy from Ludwig Maximilian University of Munich in 1908; his thesis examined the development of metaphysics in Persia."}, {"icon": "🏛️", "title": "Knighthood", "description": "Knighted by the British Crown in 1922 for his literary contributions."}, {"icon": "🌍", "title": "Pan-Islamic Philosopher", "description": "His poetry inspired Muslim intellectuals from Egypt to Indonesia."}]$wch$::jsonb,
  quotes = $wch$[{"text": "Khudi ko kar buland itna ke har taqdeer se pehle, Khuda bande se khud pooche bata teri raza kya hai.", "context": "From Bang-e-Dra — on elevating the self"}, {"text": "Nations are born in the hearts of poets, they prosper and die in the hands of politicians.", "context": "Widely attributed to Iqbal (attributed saying, not verbatim-sourced)"}, {"text": "Rise above sectional interests and private ambitions... Pass from matter to spirit.", "context": "Allahabad Address, 1930"}]$wch$::jsonb,
  description_sections = $wch$[{"title": "Early Life & Education", "content": "Born in Sialkot in 1877, Iqbal showed early aptitude for Persian and Urdu poetry. He studied at Government College Lahore under Sir Thomas Arnold, who encouraged him to study Western philosophy. He later studied at Cambridge, then earned a doctorate in Munich with his thesis on Persian metaphysics."}, {"title": "Philosophy of Khudi (Self)", "content": "Iqbal's central philosophical concept is Khudi — the development of the individual self through action, love and creative power. Drawing on Rumi, Nietzsche and Bergson, he argued that spiritual vitality begins with self-affirmation, not self-negation. This philosophy became the intellectual foundation for Muslim political awakening in South Asia."}, {"title": "Legacy in Pakistan", "content": "Iqbal's Allahabad Address of 1930 is considered the intellectual seed of Pakistan. He is buried at the entrance of Lahore's Badshahi Mosque. His birthday, 9 November (Iqbal Day), is a public holiday in Pakistan — restored by federal notification in 2022 after a suspension that began in 2015."}]$wch$::jsonb
WHERE slug = 'allama-iqbal';

-- ── (a2) Imran Khan: timeline order + one hospital figure ──
UPDATE personalities SET
  timeline = $wch$[{"year": "1971", "title": "Test debut", "description": "Made Test cricket debut for Pakistan at Edgbaston, Birmingham."}, {"year": "1992", "title": "World Cup victory", "description": "Led Pakistan to its only Cricket World Cup title at the Melbourne Cricket Ground."}, {"year": "1994", "title": "Shaukat Khanum Hospital", "description": "Opened Pakistan's first dedicated cancer hospital, where — by the hospital's own published figures — more than 75% of patients are treated free of charge or with financial support."}, {"year": "1996", "title": "Founded PTI", "description": "Founded Pakistan Tehreek-e-Insaf political party with an anti-corruption platform."}, {"year": "2018", "title": "Prime Minister", "description": "Elected as Pakistan's 22nd Prime Minister after PTI's election victory."}]$wch$::jsonb,
  description_sections = $wch$[{"title": "Cricket Career", "content": "Imran Khan played international cricket for Pakistan from 1971 to 1992, captaining the side for much of that period. His all-round ability — combining 362 Test wickets with 3,807 Test runs — placed him among the greatest all-rounders of the 20th century."}, {"title": "Humanitarian Work", "content": "After retiring from cricket, Imran devoted himself to philanthropy. Shaukat Khanum Memorial Cancer Hospital, which he built in memory of his mother, now treats more than 75% of its patients free of charge or with financial support (the hospital's own published figure) and is the largest cancer-care network in Pakistan."}]$wch$::jsonb
WHERE slug = 'imran-khan';

