  ($wch$faiz-ahmed-faiz$wch$, $wch$Faiz Ahmed Faiz$wch$, $wch$Poet of Resistance & Romance$wch$, $wch$Poet$wch$, $wch$13 February 1911$wch$, $wch$20 November 1984$wch$, $wch$Pakistani$wch$, $wch$lahore$wch$, $wch$punjab$wch$, $wch$pakistan$wch$, $wch$Lahore$wch$, $wch$Punjab$wch$, $wch$Pakistan$wch$, $wch$Faiz Ahmed Faiz, born in Narowal district and formed by Lahore, fused romance and revolution in Urdu poetry like no one before him. Editor, trade unionist and exile, he spent his last years in Lahore, where he died in 1984 and where his verse remains part of the city’s air.$wch$, $wch$[{"icon": "🖊️", "title": "Voice of a Generation", "description": "His ghazals and nazms made political longing singable across South Asia."}, {"icon": "🕊️", "title": "Lenin Peace Prize (1962)", "description": "Awarded the international peace prize for literature and activism."}, {"icon": "📰", "title": "Founding Editor", "description": "First editor of the Pakistan Times, shaping post-Partition journalism."}]$wch$::jsonb, $wch$[{"year": "1911", "title": "Born near Sialkot", "description": "Born in Kala Qader village, Sialkot district (now Narowal)."}, {"year": "1935", "title": "First collection", "description": "Begins publishing the poetry that becomes Naqsh-e-Faryadi (1941)."}, {"year": "1947", "title": "Editor in Lahore", "description": "Becomes the first editor of the Pakistan Times in Lahore."}, {"year": "1979", "title": "Lenin Peace Prize", "description": "Receives the Lenin Peace Prize for his poetry and activism."}, {"year": "1984", "title": "Dies in Lahore", "description": "Passes away in Lahore; his funeral draws the city’s literary world."}]$wch$::jsonb, $wch$[{"title": "Naqsh-e-Faryadi", "year": "1941", "description": "First major collection, blending love and social conscience.", "type": "Poetry"}, {"title": "Nuskha Haye Wafa", "description": "The collected works (kulliyat) of his poetry.", "type": "Poetry"}, {"title": "Mujh Se Pehli Si Mohabbat", "description": "His most quoted poem — a turn from private love to public sorrow.", "type": "Poem"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#7A1F1F$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Faiz_Ahmed_Faiz"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q381296"}]$wch$::jsonb, false),
  ($wch$habib-jalib$wch$, $wch$Habib Jalib$wch$, $wch$The People’s Poet$wch$, $wch$Poet$wch$, $wch$24 March 1928$wch$, $wch$13 March 1993$wch$, $wch$Pakistani$wch$, $wch$lahore$wch$, $wch$punjab$wch$, $wch$pakistan$wch$, $wch$Lahore$wch$, $wch$Punjab$wch$, $wch$Pakistan$wch$, $wch$Habib Jalib, born in Hoshiarpur and settled in Lahore, was Pakistan’s street-corner revolutionary poet — jailed by successive regimes, he recited defiance to crowds in plain, unforgettable language. Lahore was his stage and his home until his death in 1993.$wch$, $wch$[{"icon": "✊", "title": "Poet of Protest", "description": "His verses became slogans of democratic movements."}, {"icon": "⛓️", "title": "Jailed, Not Silenced", "description": "Imprisoned repeatedly rather than stop reciting."}, {"icon": "🎤", "title": "Public Mushaira Legend", "description": "Drew vast crowds with direct, musical Urdu."}]$wch$::jsonb, $wch$[{"year": "1928", "title": "Born in Hoshiarpur", "description": "Born in British Punjab; migrates to Pakistan after Partition."}, {"year": "1950s", "title": "Voice of the Streets", "description": "Rises as a public poet of protest in Lahore’s gatherings."}, {"year": "1970s", "title": "Defies Martial Law", "description": "Imprisoned under Zia-ul-Haq for refusing silence."}, {"year": "1993", "title": "Dies in Lahore", "description": "Passes away in Lahore, mourned as the people’s poet."}]$wch$::jsonb, $wch$[{"title": "Dastoor", "description": "His signature poem of defiance against unjust rule — \"Main nahin manta\" (I refuse to accept).", "type": "Poem"}, {"title": "Kuliyat-e-Habib Jalib", "description": "Collected works of his poetry.", "type": "Poetry"}]$wch$::jsonb, $wch$[{"text": "Main nahin manta, main nahin janta.", "context": "From his poem \"Dastoor\" — I do not accept, I do not acknowledge (this unjust order)."}]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#5B3A1E$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Habib_Jalib"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q5636783"}]$wch$::jsonb, false),
  ($wch$ashfaq-ahmed$wch$, $wch$Ashfaq Ahmed$wch$, $wch$Writer, Playwright & Sage of the Airwaves$wch$, $wch$Writer and broadcaster$wch$, $wch$22 August 1925$wch$, $wch$7 September 2004$wch$, $wch$Pakistani$wch$, $wch$lahore$wch$, $wch$punjab$wch$, $wch$pakistan$wch$, $wch$Lahore$wch$, $wch$Punjab$wch$, $wch$Pakistan$wch$, $wch$Ashfaq Ahmed, born in Muktsar and based in Lahore, wrote fiction and drama steeped in Punjabi soil and Sufi reflection. His radio and television presence — above all the storytelling persona of Baba Sahib in "Zavia" — made him a household sage across Pakistan.$wch$, $wch$[{"icon": "📚", "title": "Master Storyteller", "description": "Among Urdu’s most loved short-story writers."}, {"icon": "📻", "title": "Voice of Radio & PTV", "description": "\"Talqeen Shah\" and \"Zavia\" reached millions."}, {"icon": "🏅", "title": "Pride of Performance", "description": "Received Pakistan’s Pride of Performance and Sitara-e-Imtiaz."}]$wch$::jsonb, $wch$[{"year": "1925", "title": "Born in Muktsar", "description": "Born in Punjab’s Muktsar; educated at Government College Lahore."}, {"year": "1950s", "title": "Radio Pakistan", "description": "Begins the broadcasting career that defines his public voice."}, {"year": "1960s", "title": "\"Aik Mohabbat Sau Afsanay\"", "description": "His celebrated short-story collection appears."}, {"year": "2004", "title": "Dies in Lahore", "description": "Passes away in Lahore, where he had lived and worked for decades."}]$wch$::jsonb, $wch$[{"title": "Aik Mohabbat Sau Afsanay", "description": "One love, a hundred tales — his signature story collection.", "type": "Stories"}, {"title": "Gaddarya", "year": "1948", "description": "Early novel of Partition-era Punjab.", "type": "Novel"}, {"title": "Zavia", "description": "Television talks in the voice of the wise elder.", "type": "TV"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#33523B$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ashfaq_Ahmed"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q3246402"}]$wch$::jsonb, false),
  ($wch$bano-qudsia$wch$, $wch$Bano Qudsia$wch$, $wch$Novelist of the Inner Life$wch$, $wch$Novelist$wch$, $wch$28 November 1928$wch$, $wch$4 February 2017$wch$, $wch$Pakistani$wch$, $wch$lahore$wch$, $wch$punjab$wch$, $wch$pakistan$wch$, $wch$Lahore$wch$, $wch$Punjab$wch$, $wch$Pakistan$wch$, $wch$Bano Qudsia, born in Amritsar and settled in Lahore after Partition, wrote "Raja Gidh" — among the most debated Urdu novels of the twentieth century. Wife of Ashfaq Ahmed, she built her own towering reputation in fiction and drama from Lahore.$wch$, $wch$[{"icon": "📖", "title": "\"Raja Gidh\"", "description": "A canonical Urdu novel, still argued over in classrooms."}, {"icon": "🎭", "title": "Drama Writer", "description": "Her plays were staples of Pakistani television."}, {"icon": "🏅", "title": "Hilal-e-Imtiaz", "description": "Received one of Pakistan’s highest civil awards."}]$wch$::jsonb, $wch$[{"year": "1928", "title": "Born in Amritsar", "description": "Born in British Punjab; migrates to Lahore in 1947."}, {"year": "1981", "title": "\"Raja Gidh\" Published", "description": "Her landmark novel on morality and heredity appears."}, {"year": "2017", "title": "Dies in Lahore", "description": "Passes away in Lahore at 88."}]$wch$::jsonb, $wch$[{"title": "Raja Gidh", "year": "1981", "description": "The vulture king — a novel of sin, heredity and society.", "type": "Novel"}, {"title": "Aatish-e-Zer-e-Paa", "description": "Stories of women and inner conflict.", "type": "Stories"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#6E3B5C$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bano_Qudsia"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q4857023"}]$wch$::jsonb, false),
  ($wch$abdus-salam$wch$, $wch$Abdus Salam$wch$, $wch$Nobel Laureate Theoretical Physicist$wch$, $wch$Physicist$wch$, $wch$29 January 1926$wch$, $wch$21 November 1996$wch$, $wch$Pakistani$wch$, $wch$lahore$wch$, $wch$punjab$wch$, $wch$pakistan$wch$, $wch$Lahore$wch$, $wch$Punjab$wch$, $wch$Pakistan$wch$, $wch$Abdus Salam, born in Jhang and educated at Government College Lahore, shared the 1979 Nobel Prize in Physics for electroweak unification — the first Pakistani and first Muslim Nobel laureate in science. He founded the ICTP in Trieste so scientists from the developing world could work at the frontier.$wch$, $wch$[{"icon": "🏆", "title": "Nobel Prize (1979)", "description": "First Pakistani Nobel laureate; shared the Physics prize."}, {"icon": "🔬", "title": "Electroweak Unification", "description": "Unified two fundamental forces on paper before experiment confirmed it."}, {"icon": "🌍", "title": "ICTP Founder", "description": "Built a home for developing-world physicists in Trieste."}]$wch$::jsonb, $wch$[{"year": "1926", "title": "Born in Jhang", "description": "Born in Punjab; a prodigy at Government College Lahore and Cambridge."}, {"year": "1951", "title": "Professor at Lahore", "description": "Returns to head mathematics at Government College Lahore."}, {"year": "1964", "title": "Founds the ICTP", "description": "Establishes the International Centre for Theoretical Physics in Trieste."}, {"year": "1979", "title": "Nobel Prize in Physics", "description": "Shares the Nobel for the electroweak theory."}, {"year": "1996", "title": "Dies in Oxford", "description": "Passes away in Oxford; buried in Rabwah, Pakistan."}]$wch$::jsonb, $wch$[{"title": "Gauge Unification of Fundamental Forces", "year": "1979", "description": "His Nobel lecture and summation of the electroweak work.", "type": "Physics"}, {"title": "Ideals and Realities", "description": "Essays on science, faith and the developing world.", "type": "Essays"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#1F3A5F$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Abdus_Salam"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q28189"}]$wch$::jsonb, false),
  ($wch$noor-jehan$wch$, $wch$Noor Jehan$wch$, $wch$Malika-e-Tarannum — Queen of Melody$wch$, $wch$Singer and actress$wch$, $wch$21 September 1926$wch$, $wch$23 December 2000$wch$, $wch$Pakistani$wch$, $wch$lahore$wch$, $wch$punjab$wch$, $wch$pakistan$wch$, $wch$Lahore$wch$, $wch$Punjab$wch$, $wch$Pakistan$wch$, $wch$Noor Jehan, born Allah Rakhi Wasai in Kasur, became the defining voice of South Asian film music — first in Lahore’s studios and Bombay, then as the grande dame of Pakistan’s own cinema. Her wartime anthem singing in 1965 made her a national institution.$wch$, $wch$[{"icon": "👑", "title": "Malika-e-Tarannum", "description": "The title \"Queen of Melody\" was conferred by a grateful industry."}, {"icon": "🎙️", "title": "Thousands of Songs", "description": "Recorded an estimated ten thousand songs across languages and decades."}, {"icon": "🇵🇰", "title": "National Icon", "description": "Awarded the Pride of Performance; her 1965 anthems are canon."}]$wch$::jsonb, $wch$[{"year": "1926", "title": "Born in Kasur", "description": "Born into a family of musicians in Kasur, Punjab."}, {"year": "1940s", "title": "Bombay Stardom", "description": "Child star turned leading singer-actress of Indian cinema."}, {"year": "1947", "title": "Chooses Pakistan", "description": "Migrates to Lahore and helps build its film industry."}, {"year": "1965", "title": "Voice of a Nation", "description": "Her patriotic songs during the 1965 war become immortal."}, {"year": "2000", "title": "Dies in Karachi", "description": "Passes away in Karachi; mourned across South Asia."}]$wch$::jsonb, $wch$[{"title": "Anmol Ghadi", "year": "1946", "description": "Her breakthrough Bombay film as singer-actress.", "type": "Film"}, {"title": "Chanway", "year": "1951", "description": "The first film she directed in Pakistan.", "type": "Film"}, {"title": "Ae Watan Ke Sajiley Jawano", "year": "1965", "description": "The patriotic anthem of the 1965 war.", "type": "Song"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#7A5B12$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Noor_Jehan"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q466955"}]$wch$::jsonb, false),
  ($wch$amrita-pritam$wch$, $wch$Amrita Pritam$wch$, $wch$Punjabi Poet of Love and Partition$wch$, $wch$Poet and novelist$wch$, $wch$31 August 1919$wch$, $wch$31 October 2005$wch$, $wch$Pakistani$wch$, $wch$lahore$wch$, $wch$punjab$wch$, $wch$pakistan$wch$, $wch$Lahore$wch$, $wch$Punjab$wch$, $wch$Pakistan$wch$, $wch$Amrita Pritam, born in Gujranwala and formed in Lahore’s literary circles, became the foremost woman’s voice in Punjabi letters. Her elegy "Ajj Aakhaan Waris Shah Nu" — addressed to Punjab’s great Sufi poet amid Partition’s violence — is recited on both sides of the border.$wch$, $wch$[{"icon": "🖊️", "title": "First Woman of Punjabi Letters", "description": "The dominant female voice of modern Punjabi poetry."}, {"icon": "📜", "title": "\"Ajj Aakhaan Waris Shah Nu\"", "description": "Partition’s most famous elegy."}, {"icon": "🏅", "title": "Jnanpith Award (1982)", "description": "India’s highest literary honour, among many awards."}]$wch$::jsonb, $wch$[{"year": "1919", "title": "Born in Gujranwala", "description": "Born in Punjab; begins publishing poetry as a teenager."}, {"year": "1930s–40s", "title": "Lahore’s Literary World", "description": "Rises in the Progressive Writers’ circle in Lahore."}, {"year": "1947", "title": "Partition Elegy", "description": "Writes \"Ajj Aakhaan Waris Shah Nu\" as Punjab burns."}, {"year": "2005", "title": "Dies in Delhi", "description": "Passes away in Delhi, honoured in both India and Pakistan."}]$wch$::jsonb, $wch$[{"title": "Ajj Aakhaan Waris Shah Nu", "year": "1947", "description": "Ode to Waris Shah over a wounded Punjab.", "type": "Poem"}, {"title": "Pinjar", "year": "1950", "description": "Novel of a woman abducted in Partition’s chaos; later a film.", "type": "Novel"}, {"title": "Rasidi Ticket", "year": "1976", "description": "Her candid autobiography — \"The Revenue Stamp\".", "type": "Memoir"}]$wch$::jsonb, $wch$[{"text": "Ajj aakhaan Waris Shah nu, kiton qabran vichon bol.", "context": "Opening of her 1947 elegy: \"Today I call on Waris Shah — speak, from among the graves.\""}]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#8A3324$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Amrita_Pritam"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q1705018"}]$wch$::jsonb, false),
  ($wch$muhammad-ali-jinnah$wch$, $wch$Muhammad Ali Jinnah$wch$, $wch$Quaid-e-Azam — Founder of Pakistan$wch$, $wch$Statesman$wch$, $wch$25 December 1876$wch$, $wch$11 September 1948$wch$, $wch$Pakistani$wch$, $wch$karachi$wch$, $wch$sindh$wch$, $wch$pakistan$wch$, $wch$Karachi$wch$, $wch$Sindh$wch$, $wch$Pakistan$wch$, $wch$Muhammad Ali Jinnah, born in Karachi, was the barrister who led the Pakistan Movement and became the country’s first Governor-General in 1947. Karachi is his birthplace, his political cradle and his burial place — the mausoleum Mazar-e-Quaid stands at the city’s heart.$wch$, $wch$[{"icon": "🇵🇰", "title": "Founder of Pakistan", "description": "Negotiated a sovereign state into being through constitutional politics."}, {"icon": "⚖️", "title": "Ambassador of Hindu-Muslim Unity", "description": "Gokhale’s famous tribute to his early bridge-building career."}, {"icon": "🏛️", "title": "First Governor-General", "description": "Head of state of the new Pakistan, 1947–48."}]$wch$::jsonb, $wch$[{"year": "1876", "title": "Born in Karachi", "description": "Born in Wazir Mansion, Karachi, to a Khoja merchant family."}, {"year": "1890s", "title": "Called to the Bar", "description": "Qualifies at Lincoln’s Inn, London; builds a Bombay practice."}, {"year": "1940", "title": "Lahore Resolution", "description": "Presides over the Muslim League session that demands separate states."}, {"year": "1947", "title": "Governor-General of Pakistan", "description": "Leads the new dominion; Karachi is its first capital."}, {"year": "1948", "title": "Dies in Karachi", "description": "Passes away in Karachi a year after independence."}]$wch$::jsonb, $wch$[{"title": "Lahore Resolution", "year": "1940", "description": "The session he presided over that set Pakistan’s course.", "type": "Politics"}, {"title": "11 August 1947 Address", "description": "His founding speech on citizenship and equal rights.", "type": "Speech"}]$wch$::jsonb, $wch$[{"text": "Unity, Faith, Discipline.", "context": "His guiding motto for the new nation."}, {"text": "No power on earth can undo Pakistan.", "context": "From his public addresses in the movement’s final years."}]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#01411C$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Muhammad_Ali_Jinnah"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q160554"}]$wch$::jsonb, false),
  ($wch$fatima-jinnah$wch$, $wch$Fatima Jinnah$wch$, $wch$Madar-e-Millat — Mother of the Nation$wch$, $wch$Dental surgeon and stateswoman$wch$, $wch$31 July 1893$wch$, $wch$9 July 1967$wch$, $wch$Pakistani$wch$, $wch$karachi$wch$, $wch$sindh$wch$, $wch$pakistan$wch$, $wch$Karachi$wch$, $wch$Sindh$wch$, $wch$Pakistan$wch$, $wch$Fatima Jinnah, born in Karachi, was a dental surgeon who left her practice to stand beside her brother Muhammad Ali Jinnah through the Pakistan Movement. In 1965 she contested the presidency itself, and Pakistan remembers her as Madar-e-Millat — Mother of the Nation.$wch$, $wch$[{"icon": "🦷", "title": "Pioneer Professional", "description": "Among the first Muslim women dental surgeons of the subcontinent."}, {"icon": "🗳️", "title": "Presidential Candidate (1965)", "description": "Her campaign electrified the country’s politics."}, {"icon": "🇵🇰", "title": "Madar-e-Millat", "description": "Honoured as Mother of the Nation for her role in the movement."}]$wch$::jsonb, $wch$[{"year": "1893", "title": "Born in Karachi", "description": "Born in Karachi, youngest of the Jinnah siblings."}, {"year": "1923", "title": "Dental Surgeon", "description": "Qualifies and opens a dental clinic in Bombay."}, {"year": "1947", "title": "First Lady of the Movement", "description": "At the Quaid’s side through independence; settles in Karachi."}, {"year": "1965", "title": "Runs for President", "description": "Contests the presidential election against Ayub Khan."}, {"year": "1967", "title": "Dies in Karachi", "description": "Passes away in Karachi; buried beside her brother."}]$wch$::jsonb, $wch$[{"title": "My Brother", "year": "1987", "description": "Her biography of Muhammad Ali Jinnah, published posthumously.", "type": "Biography"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#2E5E4E$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Fatima_Jinnah"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q464947"}]$wch$::jsonb, false),
  ($wch$abdul-sattar-edhi$wch$, $wch$Abdul Sattar Edhi$wch$, $wch$Humanitarian — Founder of the Edhi Foundation$wch$, $wch$Humanitarian$wch$, $wch$28 February 1928$wch$, $wch$8 July 2016$wch$, $wch$Pakistani$wch$, $wch$karachi$wch$, $wch$sindh$wch$, $wch$pakistan$wch$, $wch$Karachi$wch$, $wch$Sindh$wch$, $wch$Pakistan$wch$, $wch$Abdul Sattar Edhi, born in Bantva, Gujarat and settled in Karachi, built from one small dispensary the largest volunteer ambulance and welfare network in Pakistan — orphanages, shelters, morgues and homes for the abandoned, run on donations and radical simplicity. Karachi was his base for seven decades.$wch$, $wch$[{"icon": "🚑", "title": "Largest Volunteer Ambulance Service", "description": "The Edhi fleet became the world’s largest volunteer ambulance network."}, {"icon": "🏠", "title": "Homes for the Abandoned", "description": "Orphanages, women’s shelters and the famous jhoolas (baby cradles)."}, {"icon": "🕊️", "title": "State Funeral", "description": "One of very few civilians accorded a full state funeral in Pakistan."}]$wch$::jsonb, $wch$[{"year": "1928", "title": "Born in Bantva", "description": "Born in Gujarat; migrates to Karachi at Partition."}, {"year": "1951", "title": "First Dispensary", "description": "Opens a small free dispensary in Karachi’s Mithadar."}, {"year": "1970s–90s", "title": "A National Network", "description": "Edhi ambulances, centres and shelters spread across Pakistan."}, {"year": "2016", "title": "Dies in Karachi", "description": "Passes away in Karachi; given a state funeral."}]$wch$::jsonb, $wch$[{"title": "Edhi Foundation", "year": "1951", "description": "The welfare organisation he founded and ran until his death.", "type": "Institution"}]$wch$::jsonb, $wch$[{"text": "No religion is higher than humanity.", "context": "His oft-stated guiding principle, recorded across his interviews and the Foundation’s materials."}]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#3E5C50$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Abdul_Sattar_Edhi"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q317465"}]$wch$::jsonb, false),
  ($wch$sadequain$wch$, $wch$Sadequain$wch$, $wch$Painter & Calligrapher$wch$, $wch$Painter and calligrapher$wch$, $wch$30 June 1923$wch$, $wch$10 February 1987$wch$, $wch$Pakistani$wch$, $wch$karachi$wch$, $wch$sindh$wch$, $wch$pakistan$wch$, $wch$Karachi$wch$, $wch$Sindh$wch$, $wch$Pakistan$wch$, $wch$Sadequain, born Syed Ahmed Ali in Amroha and based in Karachi, fused calligraphy and modern painting into a style recognised worldwide — giant murals, cactus-thorn figures and Quranic calligraphy panels, most of them given away rather than sold. He died in Karachi in 1987.$wch$, $wch$[{"icon": "🎨", "title": "Calligraphy-Modernist", "description": "Merged Islamic calligraphy with modernist figuration."}, {"icon": "🖼️", "title": "Public Murals", "description": "His ceiling and wall works anchor major Pakistani institutions."}, {"icon": "🎁", "title": "Art Given Away", "description": "Donated the bulk of his enormous output to institutions and friends."}]$wch$::jsonb, $wch$[{"year": "1923", "title": "Born in Amroha", "description": "Born in British India; trains as a calligrapher-copyist."}, {"year": "1940s–50s", "title": "Karachi Canvas", "description": "Settles in Karachi after Partition; fame grows through the 1950s."}, {"year": "1960s", "title": "Murals & Calligraphy", "description": "Paints monumental works for public buildings across Pakistan."}, {"year": "1987", "title": "Dies in Karachi", "description": "Passes away in Karachi, leaving thousands of works."}]$wch$::jsonb, $wch$[{"title": "Frere Hall Ceiling, Karachi", "description": "His vast calligraphic ceiling mural — a Karachi landmark.", "type": "Mural"}, {"title": "Rubaiyat Illustrations", "description": "Illustrated editions of Omar Khayyam’s quatrains in his own hand.", "type": "Illustration"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#4A2E5C$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sadequain"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q732347"}]$wch$::jsonb, false),
  ($wch$mehdi-hasan$wch$, $wch$Mehdi Hasan$wch$, $wch$Shahenshah-e-Ghazal — King of Ghazal$wch$, $wch$Singer$wch$, $wch$18 July 1927$wch$, $wch$13 June 2012$wch$, $wch$Pakistani$wch$, $wch$karachi$wch$, $wch$sindh$wch$, $wch$pakistan$wch$, $wch$Karachi$wch$, $wch$Sindh$wch$, $wch$Pakistan$wch$, $wch$Mehdi Hasan, born in Luna, Rajasthan and settled in Karachi, gave the Urdu ghazal its modern concert voice — a classically trained, velvet delivery that made poets from Ghalib to Faiz beloved of millions. Pakistan named him Shahenshah-e-Ghazal, the Emperor of Ghazal.$wch$, $wch$[{"icon": "👑", "title": "Shahenshah-e-Ghazal", "description": "The undisputed emperor of the sung ghazal."}, {"icon": "🎼", "title": "Classical Foundation", "description": "Brought raga discipline to popular singing."}, {"icon": "🏅", "title": "Pride of Performance", "description": "Among many national honours for a six-decade career."}]$wch$::jsonb, $wch$[{"year": "1927", "title": "Born in Luna", "description": "Born into a family of court musicians in Rajasthan."}, {"year": "1947", "title": "Settles in Karachi", "description": "Migrates to Pakistan; works briefly as a mechanic before music claims him."}, {"year": "1950s–60s", "title": "Radio to Playback", "description": "Rises on Radio Pakistan, then dominates film playback."}, {"year": "2012", "title": "Dies in Karachi", "description": "Passes away in Karachi after a long illness."}]$wch$::jsonb, $wch$[{"title": "Ranjish Hi Sahi", "description": "His signature ghazal — longing rendered in velvet.", "type": "Song"}, {"title": "Ab Ke Hum Bichde", "description": "The farewell ghazal generations know by heart.", "type": "Song"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#274156$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Mehdi_Hasan"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q395249"}]$wch$::jsonb, false),
  ($wch$abdul-qadeer-khan$wch$, $wch$Abdul Qadeer Khan$wch$, $wch$Nuclear Scientist$wch$, $wch$Nuclear scientist$wch$, $wch$1 April 1936$wch$, $wch$10 October 2021$wch$, $wch$Pakistani$wch$, $wch$islamabad$wch$, $wch$islamabad-capital-territory$wch$, $wch$pakistan$wch$, $wch$Islamabad$wch$, $wch$Islamabad Capital Territory$wch$, $wch$Pakistan$wch$, $wch$Abdul Qadeer Khan, born in Bhopal and settled in Pakistan, was the metallurgist who built and led the Khan Research Laboratories at Kahuta, near Islamabad — the centre of Pakistan’s uranium enrichment programme. The capital was his home and workplace for the decisive decades of his career.$wch$, $wch$[{"icon": "🔬", "title": "Built KRL", "description": "Founded and led the laboratories at the heart of the enrichment programme."}, {"icon": "🏅", "title": "Nishan-e-Imtiaz (twice)", "description": "Received Pakistan’s highest civil award twice — a rare distinction."}, {"icon": "🎓", "title": "Metallurgist", "description": "Trained in Berlin, Delft and Leuven in physical metallurgy."}]$wch$::jsonb, $wch$[{"year": "1936", "title": "Born in Bhopal", "description": "Born in British India; migrates to Pakistan in 1952."}, {"year": "1976", "title": "Founds KRL", "description": "Returns to lead the enrichment project that becomes Khan Research Laboratories."}, {"year": "1998", "title": "Nuclear Tests", "description": "Pakistan conducts its nuclear tests; Khan is the programme’s public face."}, {"year": "2021", "title": "Dies in Islamabad", "description": "Passes away in Islamabad; buried in the capital with state honours."}]$wch$::jsonb, $wch$[{"title": "Khan Research Laboratories", "year": "1976", "description": "The research institution he founded at Kahuta.", "type": "Institution"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#31456B$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Abdul_Qadeer_Khan"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q310773"}]$wch$::jsonb, false),
  ($wch$benazir-bhutto$wch$, $wch$Benazir Bhutto$wch$, $wch$Twice Prime Minister of Pakistan$wch$, $wch$Politician$wch$, $wch$21 June 1953$wch$, $wch$27 December 2007$wch$, $wch$Pakistani$wch$, $wch$islamabad$wch$, $wch$islamabad-capital-territory$wch$, $wch$pakistan$wch$, $wch$Islamabad$wch$, $wch$Islamabad Capital Territory$wch$, $wch$Pakistan$wch$, $wch$Benazir Bhutto, born in Karachi, led the Pakistan Peoples Party from exile to power and twice governed from Islamabad as prime minister — the first woman to lead a Muslim-majority country. She was assassinated in Rawalpindi in 2007 while campaigning for a third term.$wch$, $wch$[{"icon": "🗳️", "title": "First Woman PM of a Muslim-Majority State", "description": "Her 1988 victory broke a global barrier."}, {"icon": "📚", "title": "Oxford & Harvard", "description": "President of the Oxford Union before politics claimed her."}, {"icon": "✊", "title": "Democracy’s Martyr", "description": "Her assassination reshaped Pakistan’s politics."}]$wch$::jsonb, $wch$[{"year": "1953", "title": "Born in Karachi", "description": "Born to Zulfikar Ali Bhutto and Begum Nusrat Bhutto."}, {"year": "1988", "title": "Prime Minister", "description": "Wins the 1988 election; governs from Islamabad at 35."}, {"year": "1993", "title": "Second Term", "description": "Returns as prime minister after the 1993 election."}, {"year": "2007", "title": "Assassinated", "description": "Killed in an attack after a rally in Rawalpindi’s Liaquat Bagh."}]$wch$::jsonb, $wch$[{"title": "Daughter of the East", "year": "1988", "description": "Her autobiography, written in exile.", "type": "Book"}, {"title": "Reconciliation", "year": "2008", "description": "Posthumous book on Islam, democracy and the West.", "type": "Book"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#7A2040$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Benazir_Bhutto"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q34413"}]$wch$::jsonb, false),
  ($wch$pervez-musharraf$wch$, $wch$Pervez Musharraf$wch$, $wch$Army Chief & President of Pakistan$wch$, $wch$Soldier and politician$wch$, $wch$11 August 1943$wch$, $wch$5 February 2023$wch$, $wch$Pakistani$wch$, $wch$islamabad$wch$, $wch$islamabad-capital-territory$wch$, $wch$pakistan$wch$, $wch$Islamabad$wch$, $wch$Islamabad Capital Territory$wch$, $wch$Pakistan$wch$, $wch$Pervez Musharraf, born in Delhi and raised in Karachi and Ankara, rose to Chief of Army Staff and in 1999 took power in Islamabad, ruling Pakistan as chief executive and then president until 2008. The capital was the seat of his government for nine years.$wch$, $wch$[{"icon": "🎖️", "title": "Four-Star General", "description": "Rose through the artillery and special forces to lead the army."}, {"icon": "🏛️", "title": "President 2001–2008", "description": "Head of state through the post-2001 realignments."}, {"icon": "📖", "title": "\"In the Line of Fire\"", "description": "His memoir became an international bestseller."}]$wch$::jsonb, $wch$[{"year": "1943", "title": "Born in Delhi", "description": "Born in British India; family migrates to Karachi in 1947."}, {"year": "1998", "title": "Army Chief", "description": "Appointed Chief of Army Staff."}, {"year": "1999–2008", "title": "Rules from Islamabad", "description": "Takes power in October 1999; president 2001–2008."}, {"year": "2023", "title": "Dies in Dubai", "description": "Passes away in Dubai; buried in Karachi."}]$wch$::jsonb, $wch$[{"title": "In the Line of Fire", "year": "2006", "description": "Memoir of his life and presidency.", "type": "Book"}]$wch$::jsonb, $wch$[]$wch$::jsonb, $wch$[]$wch$::jsonb, NULL, NULL, NULL, $wch$#3F4A3A$wch$, $wch$[{"name": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pervez_Musharraf"}, {"name": "Wikidata", "url": "https://www.wikidata.org/wiki/Q40495"}]$wch$::jsonb, false)
